import statistics

def rhae(agent_actions, human_lists, cap=100.0):
    """agent_actions: {game: actions}; human_lists: {game: [a1, a2, ...]}."""
    scores = {}
    for game, acts in agent_actions.items():
        base = statistics.median(human_lists[game])
        scores[game] = 0.0 if acts <= 0 else min(cap, cap * base / acts)
    mean = sum(scores.values()) / len(scores)
    perfect = sum(1 for s in scores.values() if s >= cap)
    return mean, perfect, len(scores)

