import torch

class GmmGatedAdapter(torch.nn.Module):
    def __init__(self, d_in, d_out, n_components=4, tau=0.0, temp=1.0):
        super().__init__()
        self.adapter = torch.nn.Linear(d_in, d_out, bias=False)
        self.means = torch.nn.Parameter(torch.randn(n_components, d_in))
        self.logvars = torch.nn.Parameter(torch.zeros(n_components, d_in))
        self.tau, self.temp = tau, temp

    def log_prob(self, x):
        # 对角高斯混合的对数密度，返回 [B]
        z = -0.5 * (((x[:, None, :] - self.means) ** 2) / self.logvars.exp()).sum(-1)
        return torch.logsumexp(z, dim=-1) - 0.5 * self.logvars.sum(-1).max()

    def gate(self, x):
        return torch.sigmoid((self.log_prob(x) - self.tau) / self.temp)

    def forward(self, x, base_out):
        return base_out + self.gate(x).unsqueeze(-1) * self.adapter(x)

import torch

def cfm_loss(v_theta, x0, x1, cond, t=None):
    """x0: source images [B,C,H,W]; x1: target-domain images; cond: instrument id."""
    b = x0.shape[0]
    if t is None:
        t = torch.rand(b, device=x0.device)
    shape = (-1,) + (1,) * (x0.dim() - 1)
    x_t = (1 - t.view(shape)) * x0 + t.view(shape) * x1   # 直线概率路径
    target = x1 - x0                                      # 路径上的常速度
    return ((v_theta(x_t, t, cond) - target) ** 2).mean()

def sample(v_theta, x0, cond, steps=32):
    x, dt = x0, 1.0 / steps
    for k in range(steps):
        x = x + dt * v_theta(x, torch.full((x.shape[0],), k * dt), cond)
    return x                                              # 沿 ODE 积分到目标域
